void CertProvisioningAsyncWaiter::GetStatus(
    std::vector<CertProvisioningProcessStatusPtr>* out_result) {
  base::RunLoop loop;
  proxy_->GetStatus(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<CertProvisioningProcessStatusPtr>* out_result
,
             std::vector<CertProvisioningProcessStatusPtr> result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

